import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.DaAAbehN.js";const m=JSON.parse('{"title":"Lesson 14: Codex Skills","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-4/lesson-14.md","filePath":"en/modules/module-4/lesson-14.md"}'),l={name:"en/modules/module-4/lesson-14.md"};function i(n,e,r,d,p,c){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="lesson-14-codex-skills" tabindex="-1">Lesson 14: Codex Skills <a class="header-anchor" href="#lesson-14-codex-skills" aria-label="Permalink to &quot;Lesson 14: Codex Skills&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Understand the concept of Codex&#39;s built-in skills and learn to use them to quickly complete complex tasks ⏱️ <strong>Estimated Time</strong>: 20 minutes 🎯 <strong>Teaching Rhythm</strong>: Explanation + hands-on demo</p></blockquote><hr><h2 id="i-what-are-skills" tabindex="-1">I. What Are &quot;Skills&quot;? <a class="header-anchor" href="#i-what-are-skills" aria-label="Permalink to &quot;I. What Are &quot;Skills&quot;?&quot;">​</a></h2><p><strong>Skills</strong> are Codex&#39;s built-in preset workflow templates.</p><p>You can think of skills as Codex&#39;s &quot;areas of expertise&quot; — each skill is pre-optimized for a specific type of task.</p><h3 id="analogy" tabindex="-1">Analogy <a class="header-anchor" href="#analogy" aria-label="Permalink to &quot;Analogy&quot;">​</a></h3><p>If Codex is an all-around assistant:</p><ul><li><strong>Without skills</strong> = You tell it &quot;help me make a PPT,&quot; and it guesses from scratch how to do it</li><li><strong>With skills</strong> = You tell it &quot;use the PPT skill to help me make a presentation,&quot; and it directly applies best practices</li></ul><hr><h2 id="ii-what-common-skills-does-codex-have" tabindex="-1">II. What Common Skills Does Codex Have? <a class="header-anchor" href="#ii-what-common-skills-does-codex-have" aria-label="Permalink to &quot;II. What Common Skills Does Codex Have?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill Name</th><th>Purpose</th><th>Best For</th></tr></thead><tbody><tr><td>PPT Generation</td><td>Auto-generate presentations based on a topic</td><td>Professionals, students</td></tr><tr><td>Web Development</td><td>Generate HTML/CSS/JS webpages</td><td>Anyone who wants to build a site quickly</td></tr><tr><td>Data Analysis</td><td>Read data files and generate analysis reports</td><td>Analysts, operations staff</td></tr><tr><td>Code Generation</td><td>Generate code from natural language descriptions</td><td>Developers, learners</td></tr><tr><td>Document Organization</td><td>Auto-organize and format documents</td><td>Administrative staff</td></tr><tr><td>Image Processing</td><td>Resize images, convert formats, etc.</td><td>Designers, content creators</td></tr></tbody></table><blockquote><p>💡 <strong>Tip</strong>: The specific list of available skills may change with version updates. Please refer to the actual interface.</p></blockquote><hr><h2 id="iii-practice-1-use-the-ppt-skill-to-generate-a-presentation" tabindex="-1">III. Practice 1: Use the PPT Skill to Generate a Presentation <a class="header-anchor" href="#iii-practice-1-use-the-ppt-skill-to-generate-a-presentation" aria-label="Permalink to &quot;III. Practice 1: Use the PPT Skill to Generate a Presentation&quot;">​</a></h2><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Open Codex and find the &quot;Skills&quot; or &quot;Extensions&quot; panel.</li><li>Select the &quot;PPT Generation&quot; skill.</li><li>Type this command:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me make a presentation about &quot;AI Development Trends in 2026&quot;.</span></span>
<span class="line"><span>Requirements: About 10 pages, including cover, table of contents, main trend analysis, and summary.</span></span></code></pre></div></li><li>Codex will: <ul><li>Search the web for relevant information</li><li>Generate an outline</li><li>Create content for each slide</li><li>Apply suitable templates and color schemes</li></ul></li><li>Review the generated PPT and provide modification feedback as needed.</li></ol><hr><h2 id="iv-practice-2-use-the-web-development-skill-to-make-a-mini-game" tabindex="-1">IV. Practice 2: Use the Web Development Skill to Make a Mini Game <a class="header-anchor" href="#iv-practice-2-use-the-web-development-skill-to-make-a-mini-game" aria-label="Permalink to &quot;IV. Practice 2: Use the Web Development Skill to Make a Mini Game&quot;">​</a></h2><h3 id="steps-1" tabindex="-1">Steps <a class="header-anchor" href="#steps-1" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Select the &quot;Web Development&quot; skill.</li><li>Type this command:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Help me make a simple Snake game webpage.</span></span>
<span class="line"><span>Requirements:</span></span>
<span class="line"><span>- Use keyboard arrow keys to control the snake&#39;s movement</span></span>
<span class="line"><span>- The snake grows and the score increases when it eats food</span></span>
<span class="line"><span>- The game ends when the snake hits a wall or itself</span></span>
<span class="line"><span>- Clean and attractive interface</span></span></code></pre></div></li><li>Codex will generate complete HTML + CSS + JavaScript code.</li><li>Save as <code>snake.html</code> and open it in a browser to play.</li></ol><hr><h2 id="v-how-to-customize-skills" tabindex="-1">V. How to Customize Skills? <a class="header-anchor" href="#v-how-to-customize-skills" aria-label="Permalink to &quot;V. How to Customize Skills?&quot;">​</a></h2><p>When you find a task you often need to do, you can ask Codex to help you create a reusable skill template.</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I need to produce a sales summary report every month. Can you help me create an automation skill for this?</span></span></code></pre></div><p>Codex might:</p><ol><li>Analyze your past report formats</li><li>Create a template file</li><li>Each time you just need to fill in new data to auto-generate the report</li></ol><hr><h2 id="vi-in-lesson-practice-checklist" tabindex="-1">VI. In-Lesson Practice Checklist <a class="header-anchor" href="#vi-in-lesson-practice-checklist" aria-label="Permalink to &quot;VI. In-Lesson Practice Checklist&quot;">​</a></h2><p>Complete the following tasks in order:</p><ul><li>[ ] Browse Codex&#39;s skill list to understand available skills</li><li>[ ] Use the PPT skill to generate a simple presentation</li><li>[ ] Use the Web Development skill to create a simple game or tool</li><li>[ ] Reflect: Which skill would be most useful for your work?</li></ul><hr><h2 id="vii-summary" tabindex="-1">VII. Summary <a class="header-anchor" href="#vii-summary" aria-label="Permalink to &quot;VII. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>What skills are</td><td>Preset workflow templates that let Codex complete specific tasks more efficiently</td></tr><tr><td>Common skills</td><td>PPT generation, web development, data analysis, code generation, etc.</td></tr><tr><td>How to use</td><td>Select in skills panel → Enter command → Review results</td></tr><tr><td>Custom skills</td><td>You can solidify common workflows into reusable templates</td></tr></tbody></table><hr><h2 id="viii-next-step" tabindex="-1">VIII. Next Step <a class="header-anchor" href="#viii-next-step" aria-label="Permalink to &quot;VIII. Next Step&quot;">​</a></h2><p><a href="./../module-5/project-1.html">→ Enter Module 5: Project Practice</a></p>`,38)])])}const u=t(l,[["render",i]]);export{m as __pageData,u as default};
